Here is the commit message:
soc: mediatek: svs: Fix memory leak in
 svs_enable_debug_write()

In svs_enable_debug_write(), the buf allocated by memdup_user_nul()
is leaked if kstrtoint() fails.

Fix this by using __free(kfree) to automatically free buf, eliminating
the need for explicit kfree() calls and preventing leaks.

Fixes: 13f1bbcfb582 ("soc: mediatek: SVS: add debug commands")
Co-developed-by: Jianhao Xu <jianhao.xu@seu.edu.cn>
Signed-off-by: Jianhao Xu <jianhao.xu@seu.edu.cn>
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
[Angelo: Added missing cleanup.h inclusion]
Signed-off-by: AngeloGioacchino Del Regno <angelogioacchino.delregno@collabora.com>

Here is the root cause:
In svs_enable_debug_write(), the buffer `buf` allocated by `memdup_user_nul()` is not freed if `kstrtoint()` fails, causing a memory leak.

Here is the patch:
 #include <linux/clk.h>
 #include <linux/completion.h>
+#include <linux/cleanup.h>
 #include <linux/cpu.h>
 #include <linux/cpuidle.h>

 static ssize_t svs_enable_debug_write(struct file *filp,
 				      const char __user *buffer,
 				      size_t count, loff_t *pos)
 {
 	struct svs_bank *svsb = file_inode(filp)->i_private;
 	struct svs_platform *svsp = dev_get_drvdata(svsb->dev);
 	int enabled, ret;
-	char *buf = NULL;
+	char *buf __free(kfree) = NULL;

 	if (count >= PAGE_SIZE)
 		return -EINVAL;

 	buf = (char *)memdup_user_nul(buffer, count);
 	if (IS_ERR(buf))
 		return PTR_ERR(buf);

 	ret = kstrtoint(buf, 10, &enabled);
 	if (ret)
 		return ret;

 	if (!enabled) {
 		svs_bank_disable_and_restore_default_volts(svsp, svsb);
 		svsb->mode_support = SVSB_MODE_ALL_DISABLE;
 	}

-	kfree(buf);
-
 	return count;
 }



